package com.ci.pipeline.auth

import javax.naming._
import javax.naming.directory._
import java.util.Hashtable
import scala.util.{Try, Success, Failure}

// CI/CD Pipeline LDAP Authentication Module
// Validates developer credentials before allowing pipeline execution

object LdapConfig {
  val baseDn: String = sys.env.getOrElse("LDAP_BASE_DN", "dc=company,dc=com")
  val ldapUrl: String = sys.env.getOrElse("LDAP_URL", "ldap://ldap.internal:389")
  val serviceAccount: String = sys.env.getOrElse("LDAP_SERVICE_DN", "cn=svc-ci,ou=services,dc=company,dc=com")
  val servicePassword: String = sys.env.getOrElse("LDAP_SERVICE_PW", "")
  val userObjectClass: String = sys.env.getOrElse("LDAP_USER_CLASS", "inetOrgPerson")
  val groupDn: String = sys.env.getOrElse("LDAP_GROUP_DN", "cn=developers,ou=groups,dc=company,dc=com")
  val searchFilterTemplate: String = sys.env.getOrElse("LDAP_SEARCH_FILTER", "(&(objectClass={0})(uid={1}))")
}

sealed trait AuthResult
case class AuthSuccess(uid: String, groups: List[String]) extends AuthResult
case class AuthFailure(reason: String) extends AuthResult

class LdapFilterBuilder {
  // RFC 4515 compliant escaping for LDAP search filter values
  private val escapeMap: Map[Char, String] = Map(
    '\\' -> "\\5c",
    '*' -> "\\2a",
    '(' -> "\\28",
    ')' -> "\\29",
    '\u0000' -> "\\00"
  )

  def escapeFilterValue(input: String): String = {
    input.flatMap(c => escapeMap.getOrElse(c, c.toString))
  }

  def buildSearchFilter(template: String, objectClass: String, uid: String): String = {
    // Apply positional substitution with escaping
    val escapedClass = escapeFilterValue(objectClass)
    val escapedUid = escapeFilterValue(uid)
    template
      .replace("{0}", escapedClass)
      .replace("{1}", escapedUid)
  }
}

class PipelineAuthenticator {
  private val filterBuilder = new LdapFilterBuilder()

  private def createContext(principal: String, credentials: String): DirContext = {
    val env = new Hashtable[String, String]()
    env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory")
    env.put(Context.PROVIDER_URL, LdapConfig.ldapUrl)
    env.put(Context.SECURITY_AUTHENTICATION, "simple")
    env.put(Context.SECURITY_PRINCIPAL, principal)
    env.put(Context.SECURITY_CREDENTIALS, credentials)
    new InitialDirContext(env)
  }

  private def resolveUserDn(ctx: DirContext, uid: String): Option[String] = {
    val searchFilter = filterBuilder.buildSearchFilter(
      LdapConfig.searchFilterTemplate,
      LdapConfig.userObjectClass,
      uid
    )
    val controls = new SearchControls()
    controls.setSearchScope(SearchControls.SUBTREE_SCOPE)
    controls.setReturningAttributes(Array("dn", "uid", "memberOf"))
    controls.setCountLimit(1)

    val results = ctx.search(LdapConfig.baseDn, searchFilter, controls)
    if (results.hasMore) {
      Some(results.next().getNameInNamespace)
    } else {
      None
    }
  }

  private def verifyGroupMembership(ctx: DirContext, userDn: String): Boolean = {
    val groupFilter = s"(&(objectClass=groupOfNames)(member=${userDn}))"
    val controls = new SearchControls()
    controls.setSearchScope(SearchControls.SUBTREE_SCOPE)
    controls.setCountLimit(1)

    val results = ctx.search(LdapConfig.baseDn, groupFilter, controls)
    results.hasMore
  }

  def authenticate(uid: String, password: String): AuthResult = {
    if (uid == null || uid.isEmpty || password == null || password.isEmpty) {
      return AuthFailure("Credentials must not be empty")
    }

    Try {
      // Step 1: Bind as service account to search for user
      val serviceCtx = createContext(LdapConfig.serviceAccount, LdapConfig.servicePassword)

      try {
        // Step 2: Resolve user DN
        val userDnOpt = resolveUserDn(serviceCtx, uid)
        userDnOpt match {
          case None => AuthFailure("User not found")
          case Some(userDn) =>
            // Step 3: Verify password by binding as user
            val userCtx = Try(createContext(userDn, password))
            userCtx match {
              case Failure(_) => AuthFailure("Invalid credentials")
              case Success(ctx) =>
                try {
                  // Step 4: Check group membership
                  if (verifyGroupMembership(serviceCtx, userDn)) {
                    AuthSuccess(uid, List(LdapConfig.groupDn))
                  } else {
                    AuthFailure("User not in required group")
                  }
                } finally {
                  ctx.close()
                }
            }
        }
      } finally {
        serviceCtx.close()
      }
    } match {
      case Success(result) => result
      case Failure(ex) => AuthFailure(s"Authentication error: ${ex.getMessage}")
    }
  }
}

// Pipeline trigger endpoint
object PipelineTrigger {
  private val authenticator = new PipelineAuthenticator()

  def triggerBuild(uid: String, password: String, branch: String): Either[String, String] = {
    authenticator.authenticate(uid, password) match {
      case AuthSuccess(user, _) =>
        Right(s"Build triggered for branch '$branch' by user '$user'")
      case AuthFailure(reason) =>
        Left(s"Authentication failed: $reason")
    }
  }
}
